/bin/bash -lc "python3 - <<'PY'
import datetime as dt
import json
import time
import urllib.error
import urllib.request

BASE = 'http://localhost:8080'
token = None

def call(path, auth=True):
    global token
    attempts = 0
    while True:
        if auth and token is None:
            token = call('/token', auth=False)['token']
        req = urllib.request.Request(BASE + path, method='POST' if path == '/token' else 'GET')
        if auth:
            req.add_header('Authorization', 'Bearer ' + token)
        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                return json.load(response)
        except urllib.error.HTTPError as e:
            attempts += 1
            if e.code == 401 and auth:
                token = None
                continue
            if e.code == 429:
                wait = e.headers.get('Retry-After')
                try:
                    delay = float(wait) if wait is not None else 1.0
                except ValueError:
                    delay = 1.0
                time.sleep(max(delay, 0))
                continue
            if attempts < 8 and e.code >= 500:
                time.sleep(1)
                continue
            raise
        except (urllib.error.URLError, TimeoutError):
            attempts += 1
            if attempts >= 8:
                raise
            time.sleep(1)

pages = []
page = 1
while True:
    data = call('/orders?page=%d' % page)
    if data['page'] "'!= page:
        raise RuntimeError('"'unexpected page')
    pages.extend(data['items'])
    if data['next'] is None:
        break
    page += 1

seen = set()
dups = 0
unique = []
for o in pages:
    if o['id'] in seen:
        dups += 1
    else:
        seen.add(o['id'])
        unique.append(o)

start = dt.datetime(2025, 3, 1, tzinfo=dt.timezone.utc)
end = dt.datetime(2025, 6, 1, tzinfo=dt.timezone.utc)
qualifying = []
for o in unique:
    when = dt.datetime.fromisoformat(o['placed_at'].replace('Z', '+00:00')).astimezone(dt.timezone.utc)
    if o['status'] == 'shipped' and start <= when < end:
        qualifying.append(o)

customers = {}
for customer_id in {o['customer_id'] for o in qualifying}:
    customers[customer_id] = call('/customers/%s' % customer_id)

by_region = {r: 0 for r in ('north', 'south', 'east', 'west')}
for o in qualifying:
    customer = customers[o['customer_id']]
    numerator = o['amount_cents'] * (100 - customer['discount_pct'])
    q, rem = divmod(numerator, 100)
    discounted = q + (1 if rem * 2 >= 100 else 0)
    by_region[customer['region']] += discounted

result = {
  'total_cents': sum(by_region.values()),
  'order_count': len(qualifying),
  'duplicates_skipped': dups,
  'by_region': by_region,
}
print(json.dumps(result, indent=2, sort_keys=False))
print('diagnostic', json.dumps({'pages': page, 'listed': len(pages), 'unique': len(unique), 'customers_cached': len(customers)}))
PY"

